<template>\n  <main class=\"parse-tree-main\">\n    <div v-if=\"sentence\" class=\"parse-tree-container\">\n      <!-- Header -->\n      <div class=\"parse-tree-header\">\n        <a href=\"/sentences\" class=\"back-link\">← Back to Sentences</a>\n        <h1>{{ sentence.sentence }}</h1>\n        <p class=\"language-info\">{{ sentence.language || 'Language' }}</p>\n      </div>\n\n      <!-- Parse Tree Visualization -->\n      <div class=\"tree-wrapper\">\n        <ParseTreeNode\n          v-if=\"sentence.tree\"\n          :node=\"sentence.tree\"\n          :depth=\"0\"\n        />\n      </div>\n\n      <!-- Audio Player (if available) -->\n      <div v-if=\"sentence.audio\" class=\"audio-section\">\n        <h2>Pronunciation</h2>\n        <audio controls class=\"audio-player\">\n          <source :src=\"sentence.audio\" type=\"audio/mpeg\" />\n          Your browser does not support the audio element.\n        </audio>\n      </div>\n    </div>\n    <div v-else class=\"not-found\">\n      <p>Sentence not found.</p>\n      <a href=\"/sentences\" class=\"back-link\">← Back to Sentences</a>\n    </div>\n  </main>\n</template>\n\n<script setup lang=\"ts\">\ndefinePageMeta({\n  layout: 'default'\n})\n\nconst route = useRoute()\nconst slug = decodeURIComponent(route.params.slug as string)\n\n// Fetch sentence by slug\nconst { data: sentence } = await useAsyncData(\n  `sentence-${slug}`,\n  () => queryCollection('sentences').path(`/sentences/${slug}`).first()\n)\n\n// SEO\nwatch(() => sentence.value, (newSentence) => {\n  if (newSentence) {\n    useSeoMeta({\n      title: `${newSentence.sentence} | Parse Trees`,\n      description: `Interactive parse tree for: ${newSentence.sentence}`,\n      ogTitle: newSentence.sentence,\n      ogDescription: `Learn the parse tree structure of this ${newSentence.language || 'language'} sentence.`,\n      ogType: 'article'\n    })\n  }\n}, { immediate: true })\n</script>\n\n<style scoped>\n.parse-tree-main {\n  max-width: 56rem;\n  margin: 0 auto;\n  padding: 3rem 1rem;\n}\n\n.parse-tree-header {\n  margin-bottom: 3rem;\n}\n\n.back-link {\n  display: inline-block;\n  margin-bottom: 1.5rem;\n  color: #0066cc;\n  text-decoration: none;\n  font-weight: 600;\n  transition: color 0.3s ease;\n}\n\n.back-link:hover {\n  color: #0052a3;\n  text-decoration: underline;\n}\n\n.parse-tree-header h1 {\n  font-family: Georgia, Garamond, serif;\n  font-size: 2.5rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n}\n\n.language-info {\n  color: #666666;\n  font-size: 1rem;\n  margin: 0;\n}\n\n.tree-wrapper {\n  margin: 2rem 0;\n  padding: 2rem;\n  background-color: #fafafa;\n  border-radius: 8px;\n  overflow-x: auto;\n}\n\n.audio-section {\n  margin-top: 3rem;\n  padding-top: 2rem;\n  border-top: 1px solid #e5e5e5;\n}\n\n.audio-section h2 {\n  font-family: Georgia, Garamond, serif;\n  font-size: 1.5rem;\n  margin-bottom: 1rem;\n}\n\n.audio-player {\n  width: 100%;\n  max-width: 400px;\n}\n\n.not-found {\n  text-align: center;\n  padding: 3rem 1rem;\n}\n\n.not-found p {\n  color: #666666;\n  margin-bottom: 1.5rem;\n}\n\n@media (max-width: 640px) {\n  .parse-tree-main {\n    padding: 2rem 1rem;\n  }\n\n  .parse-tree-header h1 {\n    font-size: 1.75rem;\n  }\n\n  .tree-wrapper {\n    padding: 1rem;\n  }\n}\n</style>